function validate(input) {
  const [n, calls] = input;
  if (!Number.isInteger(n) || n < -1000 || n > 1000) return 'n must be an integer from -1000 to 1000.';
  if (!Array.isArray(calls) || calls.length > 1000) return 'Give at most 1000 calls.';
  if (calls.some(call => call !== 'call')) return 'Every entry of calls must be "call".';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [n, calls] = input, results = [];
  const counter = solve(n);
  if (typeof counter !== 'function') throw new Error('createCounter must return a function.');
  for (let i = 0; i < calls.length; i++) {
    const value = counter();
    if (typeof value !== 'number') throw new Error('counter() must return a number.');
    kit.trace(`counter() returns ${value}`);
    results.push(value);
  }
  return results;
}

